/* One daily Panchang summary. Preserve Moon rashi and day length from the original view. */
(()=>{'use strict';
function extras(daily,summary){if(!daily||!summary)return;const values=summary.querySelectorAll('.almanac-value'),selected=[values[5],values[8]].filter(Boolean);if(!selected.length)return;let mount=daily.querySelector('.tp-summary-extras');if(!mount){mount=document.createElement('dl');mount.className='tp-summary-extras';daily.append(mount);}const signature=selected.map(n=>n.textContent).join('|');if(mount.dataset.signature===signature)return;mount.dataset.signature=signature;mount.replaceChildren(...selected.map(n=>n.cloneNode(true)));}
function clean(root){if(!root)return;const daily=root.querySelector('.tp-dinvisesh'),grid=root.querySelector('.almanac-report>dl.almanac-grid');if(daily&&grid){extras(daily,grid);grid.remove();}}
function screen(){extras(document.querySelector('#tp-daily-extension .tp-dinvisesh'),document.getElementById('tp-summary'));}
function init(){const api=window.KPTransitPanchang;if(!api)return;const previous=api.snapshot;window.KPTransitPanchang=Object.freeze({...api,snapshot(...args){const box=document.createElement('div');box.innerHTML=previous.apply(api,args);const daily=window.KPTransitPanchangDinvisesh?.snapshot();if(daily){const extension=document.createElement('div');extension.dataset.tpDinviseshReport='true';extension.innerHTML=daily;box.append(extension);}clean(box);return box.innerHTML;}});const render=window.renderReport;window.renderReport=function(...args){const result=render.apply(this,args);clean(document.querySelector('#printReport [data-report-section="transit-panchang"]'));return result;};const observer=new MutationObserver(screen);for(const id of ['tp-summary','tp-daily-extension']){const node=document.getElementById(id);if(node)observer.observe(node,{childList:true});}screen();}
window.KPPanchangSingleSummary=Object.freeze({clean});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,400));else init();})();
